window.ScripturaLexicons.BDAG_PART_0215 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-01\" data-source=\"BDAG\" data-search=\"λαθ- remissão veja λανθάνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαθ-</td><td>remissão</td><td>veja λανθάνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-02\" data-source=\"BDAG\" data-search=\"λάθρᾳ advérbio secretamente; pelas costas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λάθρᾳ</td><td>advérbio</td><td>secretamente; pelas costas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-03\" data-source=\"BDAG\" data-search=\"λαθροδήκτης, ου, ὁ substantivo masculino aquele que morde às escondidas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαθροδήκτης, ου, ὁ</td><td>substantivo masculino</td><td>aquele que morde às escondidas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-04\" data-source=\"BDAG\" data-search=\"λαϊκός, ή, όν adjetivo leigo; não oficial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαϊκός, ή, όν</td><td>adjetivo</td><td>leigo; não oficial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-05\" data-source=\"BDAG\" data-search=\"λαῖλαψ, απος, ἡ substantivo feminino vendaval; furacão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαῖλαψ, απος, ἡ</td><td>substantivo feminino</td><td>vendaval; furacão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-06\" data-source=\"BDAG\" data-search=\"λακάω verbo rebentar; romper-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λακάω</td><td>verbo</td><td>rebentar; romper-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-07\" data-source=\"BDAG\" data-search=\"λάκκος, ου, ὁ substantivo masculino fosso; covil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λάκκος, ου, ὁ</td><td>substantivo masculino</td><td>fosso; covil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-08\" data-source=\"BDAG\" data-search=\"λακτίζω verbo dar coices; resistir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λακτίζω</td><td>verbo</td><td>dar coices; resistir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-09\" data-source=\"BDAG\" data-search=\"λαλέω verbo falar; proferir palavras; comunicar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαλέω</td><td>verbo</td><td>falar; proferir palavras; comunicar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-10\" data-source=\"BDAG\" data-search=\"λαλιά, ᾶς, ἡ substantivo feminino fala; discurso; maneira de falar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαλιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>fala; discurso; maneira de falar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-11\" data-source=\"BDAG\" data-search=\"λαμά partícula interrogativa por quê? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμά</td><td>partícula interrogativa</td><td>por quê?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-12\" data-source=\"BDAG\" data-search=\"λαμβάνω verbo tomar; receber; obter; agarrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμβάνω</td><td>verbo</td><td>tomar; receber; obter; agarrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-13\" data-source=\"BDAG\" data-search=\"Λάμεχ, ὁ nome próprio masculino indeclinável Lameque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λάμεχ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Lameque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-14\" data-source=\"BDAG\" data-search=\"λαμπάς, άδος, ἡ substantivo feminino tocha; lâmpada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμπάς, άδος, ἡ</td><td>substantivo feminino</td><td>tocha; lâmpada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-15\" data-source=\"BDAG\" data-search=\"λαμπηδών, όνος, ἡ substantivo feminino claridade; brilho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμπηδών, όνος, ἡ</td><td>substantivo feminino</td><td>claridade; brilho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-16\" data-source=\"BDAG\" data-search=\"λαμπρός, ά, όν adjetivo brilhante; resplandecente; claro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμπρός, ά, όν</td><td>adjetivo</td><td>brilhante; resplandecente; claro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-17\" data-source=\"BDAG\" data-search=\"λαμπρότης, ητος, ἡ substantivo feminino brilho; esplendor; brilhantismo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμπρότης, ητος, ἡ</td><td>substantivo feminino</td><td>brilho; esplendor; brilhantismo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-18\" data-source=\"BDAG\" data-search=\"λαμπρῶς advérbio esplendidamente; suntuosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λαμπρῶς</td><td>advérbio</td><td>esplendidamente; suntuosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-19\" data-source=\"BDAG\" data-search=\"λάμπω verbo brilhar; resplandecer; cintilar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λάμπω</td><td>verbo</td><td>brilhar; resplandecer; cintilar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0215-20\" data-source=\"BDAG\" data-search=\"λανθάνω verbo passar despercebido; ficar oculto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λανθάνω</td><td>verbo</td><td>passar despercebido; ficar oculto</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0215-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαθ-</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαθ</span>- veja <span class=\"greek\">λανθάνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λάθρᾳ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λάθρᾳ</span> advérbio (sobre a grafia com ou sem <span class=\"greek\">ι</span> veja B-D-F §26; W-S. §5, 11c; Mlt-H. 84; Boisacq 549) (veja <span class=\"greek\">λανθάνω</span>; Hom. [<span class=\"greek\">λάθρῃ</span>] e outros; SIG 609, 6 [?]; UPZ 19, 28 [163 a.C.]; BGU 1141, 48; TestSol; TestJud 5:4).</p><p class=\"entry-text\">① (fazer algo) sem o conhecimento dos demais, secretamente; empregado como advérbio (Diod S 11, 88, 4; 11, 91, 2; Dt 13:7 <span class=\"greek\">λ</span>. <span class=\"greek\">λέγειν</span>; 1 Macc 9:60; Jos., Bell. 2, 408) em oposição a <span class=\"greek\">φανερῶς</span> (TestSol 4:6; Diod S 16, 24, 2; Appian, Bell. Civ. 3, 91 §376; Cass. Dio 69, 13, 1) IPhld 6:3; cf. GMary 463, 13; <span class=\"greek\">ἀπολύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:19</a> (assim também GJs 14:1). <span class=\"greek\">ἐκβάλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:37</a>. <span class=\"greek\">καλεῖν</span> (Jos., Vi. 388) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a>. <span class=\"greek\">ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:33</a> variante textual <span class=\"greek\">φωνεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:28</a>. <span class=\"greek\">λαλεῖν</span> GMary 463, 13.</p><p class=\"entry-text\">② (fazer algo) sem seguir os procedimentos apropriados, sem o conhecimento de alguém, pelas costas de alguém; como preposição com genitivo (Hom.+; Diod S 5, 65, 4 <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>; Sb 6222, 17; Ps 100:5 <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">αὐτοῦ</span>) <span class=\"greek\">λ</span>. <span class=\"greek\">ἐπισκόπου</span> ISm 9:1.—DELG s.v. <span class=\"greek\">λανθάνω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαθροδήκτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαθροδήκτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">λάθρᾳ</span>, <span class=\"greek\">δάκνω</span>; Phryn. em Bekker, Anecdot. p. 50; Chrysostom, Hom. 15, 4 sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a> em MPG LXII 111 <span class=\"greek\">οἱ</span> <span class=\"greek\">λαθροδῆκται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κυνῶν</span>.—Aesop, Fab. 332 P.=224 H.=Babr. 104 Cr. <span class=\"greek\">λάθρῃ</span> <span class=\"greek\">κύων</span> <span class=\"greek\">ἔδακνε</span>; Paroem. Gr.: Zenob. 4, 90 <span class=\"greek\">κύων</span> <span class=\"greek\">λάθρᾳ</span> <span class=\"greek\">δάκνων</span>) aquele que morde em segredo, às escondidas, dito de cães IEph 7:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαϊκός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαϊκός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (literalmente «pertencente ao povo, comum»; termo que indica condição social; PLille 10, 4; 7 [III a.C.]; PStras 93, 4 [II a.C.]; BGU 1053 II, 10 [I a.C.]; não na LXX, mas em 1 Km 21:4 Aq., Sym., Theod.; Ezk 48:15 Sym., Theod., 22:26 Sym.; Ps.-Clem., Hom. p. 7, 38 Lagarde; Clem. Al., Strom. 3, 90, 1; 5, 33, 3 e nos escritores cristãos posteriores) referente a quem não exerce uma função oficial, leigo, por oposição aos ministros nomeados, <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἄνθρωπος</span> a pessoa leiga 1 Cl 40:5. <span class=\"greek\">τὰ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">προστάγματα</span> prescrições destinadas à pessoa leiga ibidem. Aqui <span class=\"greek\">λ</span>. é contraposto ao sacerdócio do Antigo Testamento, mas com referência evidente à situação da comunidade cristã.—Lampe s.v. 2. DELG s.v. <span class=\"greek\">λαός</span>. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαῖλαψ, απος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαῖλαψ</span>, <span class=\"greek\">απος</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; Plut., Tim. 28, 3; Sb 4324, 15; LXX; TestJob 42:1; Philo, Mut. Nom. 214; SibOr 8, 204) vendaval, furacão (Ps.-Aristot., De Mundo 4 p. 395a, 7 define-o como <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">εἱλούμενον</span> <span class=\"greek\">κάτωθεν</span> <span class=\"greek\">ἄνω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:17</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">ἀνέμου</span> (TestNapht 6:4) uma violenta rajada de vento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:23</a> (Semonides 1, 15ff Diehl3 <span class=\"greek\">ἐν</span> <span class=\"greek\">θαλάσσῃ</span> <span class=\"greek\">λαίλαπι</span> <span class=\"greek\">κλονεύμενοι</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">κύμασιν</span> <span class=\"greek\">πολλοῖσι</span> … <span class=\"greek\">θνῄσκουσιν</span>).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λακάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λακάω</span> (PGM 4, 3074 <span class=\"greek\">σίδηρος</span> <span class=\"greek\">λακᾷ</span>=«o ferro se parte, rebenta»; Hippiatr. I 423, 16f <span class=\"greek\">φλύκταιναι</span> … <span class=\"greek\">διαλακῶσιν</span> [como presente do indicativo]=«as bolhas estouram». Por isso, as formas ambíguas [Aristoph., Nub. <span class=\"greek\">διαλακήσασα</span> 410; AcThom 33: Aa II 2 p. 150, 18b <span class=\"greek\">ἐλάκησεν</span>; PGM 12, 197 <span class=\"greek\">λακηθῇ</span>] também devem ser atribuídas ao presente <span class=\"greek\">λακάω</span>, e não a <span class=\"greek\">λακέω</span> [como em B-D-F §101 p. 46; Mlt-H. 246]) romper-se, rebentar, abrir-se <span class=\"greek\">ἐλάκησεν</span> <span class=\"greek\">μέσος</span> ele rebentou pelo meio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a> (cf. Papias [3:1]).—Veja Beginn. V 22–30 para material patrístico sobre a morte de Judas.—DELG s.v. <span class=\"greek\">λάσκω</span>. M-M s.v. <span class=\"greek\">λακέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λάκκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λάκκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt., Aristoph.+; GDI 5056, 4; 5060, 60; 64 [Creta]; Sb 7167, 7; LXX, Test12Patr; ParJer 3:13; Philo; Jos., Bell. 5, 164; 7, 291 al.; Just., D. 19, 2) fosso, cova, covil <span class=\"greek\">λ</span>. <span class=\"greek\">λεόντων</span> 1 Cl 45:6 (cf. Da 6:6ff; Jos., Ant. 10, 253).—DELG s.v. 1 <span class=\"greek\">λάκκος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λακτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λακτίζω</span> (<span class=\"greek\">λάξ</span> advérbio: «com o pé»; Hom. e outros; Herodas 7, 118; BGU 1007, 7 [III a.C.]; PTebt 798, 15 [II a.C.]; Jos., Ant. 4, 278) dar coices, dito de animais de tração, como figura de resistência irracional: <span class=\"greek\">πρὸς</span> <span class=\"greek\">κέντρα</span> contra o aguilhão do condutor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:6</a> variante textual; 26:14 (veja <span class=\"greek\">κέντρον</span> 2).—DELG s.v. <span class=\"greek\">λάξ</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαλέω</span> imperfeito <span class=\"greek\">ἐλάλουν</span>; futuro <span class=\"greek\">λαλήσω</span>; 1 aoristo <span class=\"greek\">ἐλάλησα</span>; perfeito <span class=\"greek\">λελάληκα</span>. Voz passiva: 1 futuro <span class=\"greek\">λαληθήσομαι</span>; 1 aoristo <span class=\"greek\">ἐλαλήθην</span>; perfeito <span class=\"greek\">λελάλημαι</span> (Soph.+). No grego antigo, usado habitualmente para comunicação informal, desde conversas triviais até tagarelice e balbucio, portanto em oposição a <span class=\"greek\">λέγω</span>; no grego posterior, a tendência, manifesta especialmente nos escritos pseudepigráficos e na literatura aqui examinada, é equipará-lo a <span class=\"greek\">λέγω</span> e ampliar-lhe o emprego anterior.</p><p class=\"entry-text\">① produzir som, soar, emitir sons ou tons (Aesop fab. 248b H.//146 H-H.//202 Ch.//variante textual 141 P.) que constituem uma espécie de fala, especialmente de coisas inanimadas (por exemplo, do eco, Cass. Dio 74, 21, 14; de correntes de água Achilles Tat. 2, 14, 8; OdeSol 11:6 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λαλοῦν</span>), do trovão <span class=\"greek\">ἐλάλησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βρονταί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:4ab</a>. <span class=\"greek\">ἐλάλησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βρονταὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">φωνάς</span> v. 3. De uma trombeta 4:1 (cf. Aristot., De Aud. p. 801a, 29 <span class=\"greek\">διὰ</span> <span class=\"greek\">τούτων</span>=flautas etc.; Achilles Tat. 2, 14, 8 da <span class=\"greek\">κιθάρα</span>). Do sangue de Cristo, que fala de maneira mais eficaz que o de Abel (Gen 4:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:24</a>; veja 11:4 (Goodsp., Probs. 188). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:29</a>.</p><p class=\"entry-text\">② proferir palavras, conversar, falar, em referência a pessoas</p><p class=\"entry-text\">ⓐ do ato de falar, intransitivamente</p><p class=\"entry-text\"><span class=\"greek\">α</span>. (ser capaz de) falar; possuir e exercer a faculdade da fala, em contraste com quem não consegue falar (cf. Ps 113:13; 134:16; 3 Macc 4:16; TestSol 10:3 C <span class=\"greek\">λ</span>. <span class=\"greek\">ἀνθρωπίνως</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:33</a>; 12:22; 15:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>, 64; 11:14. <span class=\"greek\">ἐλάλει</span> <span class=\"greek\">ὀρθῶς</span> ele conseguia falar claramente (em contraste com as emissões ininteligíveis de um surdo-mudo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:35</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. falar, expressar-se (Aesop, Fab. 146 H-H. e outros) <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λαλοῦντες</span> não sois vós que falareis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:20</a> (cf. TestAbr A 6 p. 83, 5 [Stone p. 14] <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαλῶν</span>; AscIs 1, 7, <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">λαλοῦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>). <span class=\"greek\">προφῆται</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">λαλείτωσαν</span> dois ou três profetas devem manifestar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:29</a>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λαλοῦντος</span> enquanto ele ainda falava <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:5</a>; 26:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:35</a>; 14:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:49</a>; 22:47, 60. <span class=\"greek\">μηκέτι</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λαλοῦντος</span> AcPl Ha 5, 14 sobre um leão (?); <span class=\"greek\">μηκέτι</span> <span class=\"greek\">λαλήσας</span> 10, 25=MartPl Aa I 115, 16.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:11ab</a>, al.—Em oposição ao ato de ouvir (Plut., Mor. 502c <span class=\"greek\">λαλοῦντι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀκούοντας</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀκούοντι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λαλούντων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:35</a>.—Em oposição ao silêncio (Lucian, Vit. Auct. 3) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤφιεν</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δαιμόνια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a> (<span class=\"greek\">λέγειν</span> variante textual). <span class=\"greek\">λάλει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σιωπήσῃς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:9</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐπιτρέπεται</span> <span class=\"greek\">λαλείν</span> (às mulheres) não é permitido manifestar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:34f</a> (cf. Plut., Mor. 142d: uma mulher deve cuidar de sua casa e permanecer calada; pois deve conversar com seu marido ou por intermédio dele). Essa passagem se refere à manifestação verbal em assembleia congregacional, que envolvia não somente o culto, mas também a discussão de assuntos da congregação; este último aspecto parece estar implícito aqui, visto que, para as mulheres helênicas, a participação em deliberações públicas contrariava o costume, diferentemente dos privilégios que tinham em certos ritos cultuais (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:5</a>) (veja Danker, Benefactor 164, com referência a IG II, 1369, 107–9; para outras opiniões, veja os comentários).—Em oposição ao agir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:12</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. A pessoa a quem ou com quem alguém fala é indicada de diversas maneiras: no dativo <span class=\"greek\">λ</span>. <span class=\"greek\">τινί</span> falar a alguém ou com alguém (Aristoph., Equ. 348; Philemon Com. 11 Kock; Menander, Periciromene 220 <span class=\"greek\">σοί</span>; Aelian, Ep. 14 p. 181, 1; Diog. L. 9, 64; pseudepigr.; Just., A I, 63, 14. <span class=\"greek\">λ</span>. <span class=\"greek\">ἑαυτῷ</span>=consigo mesmo; Lev 1:1f; Ezk 33:30b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46ab</a>, 47; 13:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:22</a>; 24:6, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:26</a> (cf. CB I/2, 566f nº 467–69 <span class=\"greek\">Ἀθάνατος</span> <span class=\"greek\">Ἐπιτύνχανος</span> diz de si mesmo: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">εἶμαι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαλῶν</span> <span class=\"greek\">πάντα</span>); 9:29; 12:29; 15:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1f</a>; por <span class=\"greek\">πρός</span> com acusativo (Plut. Mor. 502c [veja <span class=\"greek\">β</span> acima]; Ps.-Lucian, Asin. 44; Gen 27:6; Ex 30:11, 17, 22; JosAs 14:7 al.; ParJer 3:5; ApcMos 28; SibOr 3, 669; Just., D. 27, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:19</a>, 55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:1</a>; 8:26; 11:20; 26:31 (cf. Lat. ire in consilium; Taubenschlag, OpMin. II 725 [a referência papirológica é insatisfatória]); por <span class=\"greek\">μετά</span> com genitivo (Gen 35:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:27</a>; 9:37; 14:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:12</a>; 10:8; 17:1; 21:9, 15. <span class=\"greek\">μὴ</span> <span class=\"greek\">διαλίπῃς</span> <span class=\"greek\">λαλῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> Hv 4, 3, 6.—A pessoa ou coisa de que se fala é indicada por <span class=\"greek\">περί</span> com genitivo (PSI 361, 5 [251 a.C.] <span class=\"greek\">λαλήσας</span> <span class=\"greek\">περί</span> <span class=\"greek\">μου</span>; PFay 126, 4 [c. 200 d.C.]; Gen 19:21; Ezk 33:30a; TestAbr B 8 p. 112 14 [Stone p. 72]; TestJob 46:7; JosAs 6:2 al.; Philo, Fuga 33, 30a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:26</a>; 12:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:5</a>; 4:8.—<span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (PPetr II, 13 (6), 9 [III a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:38</a>; 9:11; na voz passiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:10</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. O modo de falar ou de proferir palavras pode ser especificado com maior precisão: <span class=\"greek\">κακῶς</span>, <span class=\"greek\">καλῶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:23</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">νήπιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:11</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">δράκων</span> (sibilava?) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:11</a>. <span class=\"greek\">στόμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">στόμα</span> face a face (cf. Num 12:8; ApcEsdr 6:6 p. 31, 10 Tdf.) 2J 12; 3J 14. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀέρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:9</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κύριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:17</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">περισσεύματος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">λαλεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:31</a> (cf. Lev 1:1 <span class=\"greek\">λ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span>). <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44</a>. <span class=\"greek\">παρρησίᾳ</span> 7:13, 26. <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> 16:29. <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:10</a>, 13. <span class=\"greek\">χωρὶς</span> <span class=\"greek\">παραβολῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:34</a>. <span class=\"greek\">λ</span>. (<span class=\"greek\">ἐν</span>) <span class=\"greek\">ψαλμοῖς</span> falar por meio de salmos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:19</a>. Quanto aos profetas <span class=\"greek\">λ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> D 11:7 (Just., D. 7, 1). Quanto a Deus <span class=\"greek\">λ</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">προφητῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:70</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. como particípio substantivado <span class=\"greek\">τὰ</span> <span class=\"greek\">λαλούμενα</span> (Paradox. Vat. 2 Keller; Jos., Ant. 16, 321; Just., D. 7, 2) <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:45</a>; 16:14. <span class=\"greek\">τὰ</span> <span class=\"greek\">λελαλημένα</span> (EpArist 299; cf. TestSol 20:21 <span class=\"greek\">τὰ</span> … <span class=\"greek\">λαληθέντα</span> <span class=\"greek\">μοι</span>) <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:45</a>.—Sobre <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">γλώσσῃ</span> e <span class=\"greek\">λ</span>. <span class=\"greek\">γλώσσαις</span>, veja <span class=\"greek\">γλῶσσα</span> 3.</p><p class=\"entry-text\">ⓑ da fala em relação ao conteúdo expresso (a capacidade de <span class=\"greek\">λ</span>. pode produzir <span class=\"greek\">λόγοι</span> Aesop, Vi. G 7f P.), transitivo falar e, desse modo, afirmar, proclamar, dizer <span class=\"greek\">τὶ</span> algo (X., Cyr. 1, 4, 1 <span class=\"greek\">πολλά</span>; Demosth. 45, 77 <span class=\"greek\">μέγα</span>; Paradox. Vat. 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀνόματα</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:34</a>. <span class=\"greek\">ῥῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:20</a> (JosAs 14:14 al.; ParJer 3:4.). <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:29</a>, 31 (<span class=\"greek\">λαλ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> como em Jos., Ant. 16, 113); 8:25; 14:25; 16:6, 32. <span class=\"greek\">τὰ</span> <span class=\"greek\">μεγαλεῖα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a> (TestJob 38:1). <span class=\"greek\">βλασφημίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:11</a> (JosAs 13:9; Just., D. 32, 3). <span class=\"greek\">σοφίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:6f</a>. <span class=\"greek\">μυστήρια</span> 14:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:3</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δέοντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:13</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">ὑπέρογκα</span> Jd 16; <span class=\"greek\">μεγάλα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:5</a>. <span class=\"greek\">τί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:49</a>. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">λαλεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:6</a>; 12:50. <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:28</a>, 30; 12:36; 17:1; AcPl Ha 10, 11. <span class=\"greek\">ἐλάλησέν</span> <span class=\"greek\">τι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">πονηρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:21</a> (cf. 3 Km 22:8, 13b; JosAs 12:5). <span class=\"greek\">ἐσύρετο</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">λαλῶν</span> (Paulo) deixou-se arrastar para dentro sem dizer palavra AcPl Ha 4, 11.—Na voz passiva, <span class=\"greek\">λαλεῖταί</span> <span class=\"greek\">τι</span>: algo é dito, proclamado, relatado (cf. a inscrição relativa à mãe e ao irmão [APF 5, 1913, 169 nº 24, 8] <span class=\"greek\">ὧν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σωφροσύνη</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμον</span> <span class=\"greek\">λελάληται</span>, também Ps 86:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a>; 9:19 <span class=\"greek\">ἡ</span> <span class=\"greek\">λαλουμένη</span> <span class=\"greek\">διδαχή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λαληθεὶς</span> <span class=\"greek\">λόγος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:2</a>. <span class=\"greek\">ἐλαλήθη</span> <span class=\"greek\">ὅτι</span> 11:18 (B-D-F §397, 3).—Frequentemente, além disso, menciona-se no dativo a pessoa a quem se fala <span class=\"greek\">ἄλλην</span> <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">ἐλάλησεν</span> <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>. <span class=\"greek\">ἐλάλει</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> ele lhes proclamava a palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>; 4:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:19</a>. <span class=\"greek\">ἐλάλησεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>; cf. v. 34. <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> … <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:50</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63</a>.—8:40 (<span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">λ</span>. como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:25</a> adiante); 14:25; 15:11; 16:1, 4, 6. <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">οἰκοδομήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:3</a>; com <span class=\"greek\">πρός</span> e acusativo (Gen 18:19; Zech 8:16) <span class=\"greek\">λόγους</span> … <span class=\"greek\">ἐλάλησα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a> (cf. Dt 10:4).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:22</a>; 11:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a>; com <span class=\"greek\">ἐν</span> e dativo <span class=\"greek\">σοφίαν</span> <span class=\"greek\">λαλοῦμεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τελείοις</span> falamos de sabedoria entre os maduros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:6</a>; com <span class=\"greek\">μετά</span> e genitivo <span class=\"greek\">λαλεῖτε</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:25</a> (cf. Zech 8:16). <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">λαλήσω</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">σοῦ</span> Hs 5, 3, 2; cf. Hs ins.—Com caracterização específica do ato de falar <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παροιμίαις</span> <span class=\"greek\">λελάληκα</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:25a</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">λαλῶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:8</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκκλησίᾳ</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νοί̈</span> <span class=\"greek\">μου</span> <span class=\"greek\">λαλῆσαι</span> 14:19. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀληθείᾳ</span> <span class=\"greek\">ἐλαλήσαμεν</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:14</a>. <span class=\"greek\">ἀφόβως</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτά</span> <span class=\"greek\">τινος</span> comunicar algo diretamente a alguém (cf. Dt 5:1) Hv 3, 8, 11 (para 4, 3, 6, veja 2a<span class=\"greek\">γ</span> acima). <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">οὖς</span> sussurrar algo ao ouvido de alguém (de modo que ninguém mais o ouça; cf. Jos., Ant. 6, 165) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>.</p><p class=\"entry-text\">③ Em diversas passagens, o conteúdo da fala é introduzido por <span class=\"greek\">λέγων</span> (veja <span class=\"greek\">λέγω</span> 1b<span class=\"greek\">θ</span><span class=\"hebrew\" dir=\"rtl\">א</span>), assim como no Antigo Testamento (Gen 34:8; 41:9; 42:22; Ex 31:12; Lev 20:1; TestAbr B 12 p. 116, 28 [Stone p. 80]; TestJob 7:1 al.; ParJer 1:1; 1:6 al.; ApcMos 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>; 14:27; 23:1; 28:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:1</a>; 17:1 al. Facultativamente: <span class=\"greek\">εἶπον</span>, veja esse verbete, ao final.—B. 1254. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαλιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαλιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Aristoph.+, sobretudo em sentido desfavorável, «mexerico, conversa banal»; assim também em Sb 2266, 13) na literatura aqui considerada, sempre em sentido positivo.</p><p class=\"entry-text\">① conteúdo da fala, discurso, ato de falar (Epict. 3, 16, 1; Himerius, Or. 64 [=Or. 18] inscrição de título [de um discurso de Himério]; Ps.-Callisth. 1, 17, 3; Is 11:3; SSol 4:3; Job 33:1; 2 Macc 8:7; TestReub 2:6; GrBar 6:16; Jos., Bell. 2, 132) <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">λαλιαί</span> não há palavra nem discurso 1 Cl 27:7 (Ps 18:4). <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σὴν</span> <span class=\"greek\">λ</span>. por causa do que disseste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:42</a>.</p><p class=\"entry-text\">② maneira de se expressar, forma ou modo de falar (helenístico, segundo Moeris 203 P.).</p><p class=\"entry-text\">ⓐ literalmente, das peculiaridades dialetais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:73</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.70\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:70</a> variante textual (veja Zahn, Einl. I3 19.—Similarly Ps.-Callisth. 2, 15, 7 de Alexandre na corte persa: <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἤλεγξε</span>; cf. <span class=\"greek\">γλῶ̣</span>[<span class=\"greek\">ττα</span>] nesse sentido Acta Alex. III, col. 3, 12).</p><p class=\"entry-text\">ⓑ da maneira característica como Jesus falava <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:43</a>.—DELG s.v. <span class=\"greek\">λαλέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμά</h1><div class=\"entry-meta\"><span>partícula interrogativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμά</span> (<span class=\"hebrew\" dir=\"rtl\">לָמָּה</span>, aramaico <span class=\"hebrew\" dir=\"rtl\">לְמָא</span>) por quê? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a> variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:34</a> variante textual (veja <span class=\"greek\">λεμά</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμβάνω</span> (Hom.+) imperfeito <span class=\"greek\">ἐλάμβανον</span>; futuro <span class=\"greek\">λήμψομαι</span> (PTurin II, 3, 48; POxy 1664, 12; sobre o <span class=\"greek\">μ</span>, veja Mayser 194f; Thackeray 108ff; B-D-F §101; W-S. §5, 30; Mlt-H. 106; 246f; Reinhold 46f; WSchulze, Orthographica 1894.—Sobre a voz média, veja B-D-F §77); 2 aoristo <span class=\"greek\">ἔλαβον</span>, imperativo <span class=\"greek\">λάβε</span> (B-D-F §101 p. 53 s.v. <span class=\"greek\">λαμβάνειν</span>; W-S. §6, 7d; Mlt-H. 209 n. 1), imperativo, 3ª pessoa do plural <span class=\"greek\">λαβέτωσαν</span> (LXX; GJs 4:2); perfeito <span class=\"greek\">εἴληφα</span> (DRinge, Glotta 62, ’84, 125–28), 2ª pessoa do singular <span class=\"greek\">εἴληφας</span> e <span class=\"greek\">εἴληφες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:17</a> variante textual (W-S. §13, 16 note; Mlt-H. 221), particípio <span class=\"greek\">εἰληφώς</span>. Passiva:: futuro, 3ª pessoa do plural <span class=\"greek\">ληφθήσονται</span> Jdth 6:9; aoristo <span class=\"greek\">εἰλήφθην</span> LXX; perfeito, 3ª pessoa do singular <span class=\"greek\">εἴληπται</span>; mais-que-perfeito, 3ª pessoa do singular <span class=\"greek\">εἴληπτο</span> (Just., D. 132, 3). Para as formas encontradas nas inscrições áticas, veja Threatte II 645. Nas subdivisões seguintes, os números 1–9 destacam uma participação ativa, enquanto 10 sugere passividade.</p><p class=\"entry-text\">① apoderar-se de algo, pondo-lhe a mão ou agarrando-o, direta ou indiretamente; tomar, segurar, agarrar, pegar nas mãos <span class=\"greek\">ἄρτον</span> (Diod S 14, 105, 3 <span class=\"greek\">ῥάβδον</span>; TestSol 2:8 D <span class=\"greek\">τὴν</span> <span class=\"greek\">σφραγῖδα</span>; TestJob 23:10 <span class=\"greek\">ψαλίδα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:26a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:22a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:35</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">βιβλίον</span> (Tob 7:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:8f</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">κάλαμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:30</a>. <span class=\"greek\">λαμπάδας</span> tomar (nas mãos) (Strattis Com. [V a.C.], Fgm. 37 K. <span class=\"greek\">λαβόντες</span> <span class=\"greek\">λαμπάδας</span>) 25:1, 3. <span class=\"greek\">λαβέτωσαν</span> <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">λαμπάδα</span> GJs 7:2. <span class=\"greek\">μάχαιραν</span> desembainhar a espada (Gen 34:25; Jos., Vi. 173 [cf. JosAs 23:2 <span class=\"greek\">τὴν</span> <span class=\"greek\">ῥομφαίαν</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:52</a>. Em uso absoluto, <span class=\"greek\">λάβετε</span>: «tomai (isto)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:26b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:22b</a>.—Segura(-me) GHb 356, 39=ISm 3:2.—<span class=\"greek\">ἔλαβέ</span> <span class=\"greek\">με</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τριχῶν</span> <span class=\"greek\">μου</span> minha mãe, o Espírito Santo, tomou-me por um dos meus cabelos GHb 20, 63. <span class=\"greek\">Ἐλισάβεδ</span> … <span class=\"greek\">λαβουμένη</span> (<span class=\"greek\">λαβοῦσα</span> codd.) <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρεινῇ</span> E. tomou (João) e subiu à região montanhosa GJs 22:3. <span class=\"greek\">λαβών</span> às vezes é empregado de modo algo pleonástico para dar vivacidade à narrativa, como em Hom. (Od. 24, 398) e dos dramaturgos (Soph., Oed. R. 1391 e outros), mas também de acordo com o uso hebraico (JViteau, Étude sur le Grec du NT 1893, 191; Dalman, Worte 16ff; Wlh., Einleitung2 1911, 14; B-D-F §419, 1 e 2; veja Rob. 1127; veja, por exemplo, ApcBar 2:1 <span class=\"greek\">λαβών</span> <span class=\"greek\">με</span> <span class=\"greek\">ἤγαγε</span>; Josh 2:4; Horapollo 2, 88 <span class=\"greek\">τούτους</span> <span class=\"greek\">λαβὼν</span> <span class=\"greek\">κατορύττει</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:31</a>, 33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:19</a>, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:25</a>; 16:3; Hs 5, 2, 4. O particípio pode ser traduzido aqui pela preposição «com» (B-D-F §418, 5; Rob. 1127) <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σπεῖραν</span> <span class=\"greek\">ἔρχεται</span> ele veio com um destacamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:3</a> (cf. Soph., Trach. 259 <span class=\"greek\">στρατὸν</span> <span class=\"greek\">λαβὼν</span> <span class=\"greek\">ἔρχεται</span>; ApcrEsd 6, 17 p. 31, 24 Tdf. <span class=\"greek\">λαβὼν</span> … <span class=\"greek\">στρατιὰν</span> <span class=\"greek\">ἀγγέλων</span>). <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> … <span class=\"greek\">τὸν</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">ἐρράντισε</span> com o sangue ele aspergiu o povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:19</a> (cf. ParJer 9:32 <span class=\"greek\">λαβόντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λίθον</span> <span class=\"greek\">ἔθηκαν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνῆμα</span> <span class=\"greek\">αὐτοῦ</span> ‘cobriram seu túmulo com uma pedra’; Mel., P. 14, 88 <span class=\"greek\">λαβόντες</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> … <span class=\"greek\">αἶμα</span>). Diferente é o uso perifrástico do particípio aoristo de <span class=\"greek\">λ</span>. com <span class=\"greek\">ἔχει</span>: Dg 10:6 <span class=\"greek\">ἃ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λαβὼν</span> <span class=\"greek\">ἔχει</span> aquilo que a pessoa recebeu de Deus (cf. Eur., Bacchae 302 <span class=\"greek\">μεταλαβὼν</span> <span class=\"greek\">ἔχει</span>; Goodwin §47; Gildersleeve, Syntax §295; Schwyzer I, 812). Frequentemente a parataxe substitui a construção participial (B-D-F §419, 5) <span class=\"greek\">ἔλαβε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐμαστίγωσεν</span> (em vez de <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ἐ</span>.) mandou açoitar Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:1</a>. <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">βαλεῖν</span> lançar o pão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:27</a>. <span class=\"greek\">ἔλαβον</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐποίησαν</span> <span class=\"greek\">τέσσερα</span> <span class=\"greek\">μέρη</span> dividiram as roupas dele em quatro partes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:23</a>.—Em sentido figurado <span class=\"greek\">ἀφορμὴν</span> <span class=\"greek\">λ</span>. encontrar oportunidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:8</a>, 11 (veja <span class=\"greek\">ἀφορμή</span>); <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">λ</span>. tomar como exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:10</a>; assim também <span class=\"greek\">λ</span>. isoladamente, <span class=\"greek\">λάβωμεν</span> <span class=\"greek\">Ἐνώχ</span> 1 Cl 9:3.—Da cruz como símbolo da morte do mártir: tomar sobre si <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:38</a> (cf. Pind., P. 2, 93 [171] <span class=\"greek\">λ</span>. <span class=\"greek\">ζυγόν</span>). Podemos incluir aqui <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτοῦ</span> ele vestiu as suas roupas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:12</a> (cf. Hdt. 2, 37; 4, 78; GrBar 9:7 <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄφιν</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">ἔνδυμα</span>). Provavelmente de maneira semelhante <span class=\"greek\">μορφὴν</span> <span class=\"greek\">δούλου</span> <span class=\"greek\">λ</span>. assumir a forma de escravo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a>.—Quanto a comida e bebida, tomar, ingerir (cf. Bel 37 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:23</a>. <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄξος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:30</a>; <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τροφὴν</span> <span class=\"greek\">ἐνίσχυσεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:19</a>; <span class=\"greek\">τροφὴν</span> … <span class=\"greek\">λα</span>[<span class=\"greek\">βεῖν</span>] AcPl Ha 1, 19. (<span class=\"greek\">βρέφος</span>) <span class=\"greek\">ἔλαβε</span> <span class=\"greek\">μασθὸν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μητρὸς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Μαρίας</span> (a criança) tomou o seio de sua mãe Maria GJs 19:2.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:4</a> (veja 10b adiante) também poderia pertencer a esta acepção.</p><p class=\"entry-text\">② tirar, remover (<span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> ApcEsdr 6:16 p. 31, 23 Tdf.) com ou sem o emprego de força <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀργύρια</span> tirar as moedas de prata (do templo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:6</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀσθενείας</span> diseases 8:17. <span class=\"greek\">τὸν</span> <span class=\"greek\">στέφανον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:11</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εἰρήνην</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> retirar a paz da terra 6:4 (<span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐκ</span> as UPZ 125, 13 <span class=\"greek\">ὸ̔</span> <span class=\"greek\">εἴληφεν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οἴκου</span>; 2 Ch 16:2; TestSol 4:15 D; TestAbr B 7 p. 111, 12 [Stone p. 70]; Mel., P. 55, 403).</p><p class=\"entry-text\">③ tomar posse de, tomar, adquirir <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὸν</span> <span class=\"greek\">χιτῶνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:40</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἕν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:27</a>. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">βασιλείαν</span> obter para si o poder régio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:12</a> (cf. Jos., Ant. 13, 220). <span class=\"greek\">λ</span>. <span class=\"greek\">γυναῖκα</span> tomar esposa (Eur., Alc. 324; X., Cyr. 8, 4, 16; Gen 4:19; 6:2; Tob 1:9; TestSol 26:1; TestJob 45:3; ParJer 8:3; Jos., Ant. 1, 253; Just., D. 116, 3; 141, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:19</a>–21; 22 variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:28</a>–31 (veja também as variantes textuais em 14:20 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:28</a>). Da própria vida, que Jesus entrega voluntariamente para retomá-la por sua própria autoridade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:18a</a>. [<span class=\"greek\">ἀπολείπ</span>]<span class=\"greek\">ετε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span>, <span class=\"greek\">λάβεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> [abandonai] as trevas, tomai a luz AcPl Ha 8, 32. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τιμὴν</span> <span class=\"greek\">λ</span>. tomar sobre si a honra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a>.—Lançar mão de alguém, agarrar, com acusativo da pessoa dominada à força (Hom. e outros; LXX; voz média com genitivo Just., A II, 2, 10, D. 105, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:35</a>, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:3</a>, 8. De um espírito maligno que se apodera do enfermo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:39</a> (cf. PGM 7, 613 <span class=\"greek\">εἴλημπται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαίμονος</span>; TestSol 17:2 <span class=\"greek\">εἰ</span> <span class=\"greek\">λήμψομαί</span> <span class=\"greek\">τινα</span>, <span class=\"greek\">εὐθέως</span> <span class=\"greek\">ἀναιρῶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ξίφει</span>; Jos., Ant. 4, 119 <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λάβῃ</span> <span class=\"greek\">πνεῦμα</span>; Just., A I, 18, 4 <span class=\"greek\">ψυχαῖς</span> <span class=\"greek\">ἀποθανόντων</span> <span class=\"greek\">λαμβανόμενοι</span>).—Especialmente de sentimentos e emoções: apoderar-se de, acometer <span class=\"greek\">τινά</span>, alguém (Hom. e outros; Ex 15:15; Wsd 11:12; Jos., Ant. 2, 139; 14, 57) <span class=\"greek\">ἔκστασις</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">ἅπαντας</span> o espanto apoderou-se de todos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:26</a>. <span class=\"greek\">φόβος</span> 7:16. Semelhantemente <span class=\"greek\">πειρασμὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἴληφεν</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀνθρώπινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>.—De caça e pesca: capturar, apanhar (X., Cyr. 1, 4, 9; Aelian, VH 4, 14) <span class=\"greek\">οὐδέν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a> variante textual Figuradamente <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">λαμβάνει</span> (<span class=\"greek\">ὑμᾶς</span>) se alguém vos engana, tirando vantagem de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:20</a> (os exemplos citados por Field, Notes, 184f, dizem respeito a espoliação material, ao passo que Paulo parece aludir às tentativas de seus adversários de controlar o pensamento dos coríntios para atender aos seus próprios objetivos políticos; veja também CLattey, JTS 44, ’43, 148); de modo semelhante <span class=\"greek\">δόλῳ</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">λ</span>. apanhar alguém mediante ardil 12:16.</p><p class=\"entry-text\">④ receber pagamento, cobrar, aceitar; em matéria de tributos etc., arrecadar o imposto de duas dracmas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:24</a>; dízimos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:8f</a>; uma parte dos frutos a título de arrendamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:34</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> algo de alguém (Plut., Mor. 209d, Aem. Paul. 5, 9) 17:25. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γεωργῶν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">καρπῶν</span> receber dos lavradores uma parte dos frutos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:2</a>.—<span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> algo de alguém (Aristarch. Sam. p. 352, 4; Jos., Ant. 5, 275; Just., D. 22, 11; Tat. 19, 1) <span class=\"greek\">οὐ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μαρτυρίαν</span> <span class=\"greek\">λ</span>. o testemunho que recebo não vem de um ser humano; ou: não aceitarei mero testemunho humano (PSI 395, 6 [241 a.C.] <span class=\"greek\">σύμβολον</span> <span class=\"greek\">λαβὲ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῶν</span>=faz com que te deem um recibo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:34</a>; cf. vveja 44; 3:11, 32f.</p><p class=\"entry-text\">⑤ incluir alguém numa experiência, acolher, receber <span class=\"greek\">τινὰ</span>, alguém, com <span class=\"greek\">εἰς</span>, «para dentro de» (Wsd 8:18) literalmente <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span> acolher alguém no barco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:21</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκίαν</span> receber alguém em casa 2J 10. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> em sua própria casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:27</a>. Receber alguém no sentido de reconhecer a autoridade dessa pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:12</a>; 5:43ab; 13:20abcd.—<span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπηρέται</span> <span class=\"greek\">ῥαπίσμασιν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἔλαβον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:65</a> não significa «os servos o prenderam mediante golpes» (BWeiss, al.), mas constitui uma expressão coloquial (veja B-D-F §198, 3, com citação de AcJo 90 [Aa II 196, 1] <span class=\"greek\">τί</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">ῥαπίσμασίν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἔλαβες</span>; ‘e se me tivesses golpeado?’ ) os servos o trataram a golpes (Moffatt: ‘deram-lhe murros e bofetadas’), ou mesmo «pegaram-no» a golpes, «espancaram-no» (talvez um latinismo; Cicero, Tusc. 2, 14, 34 verberibus accipere. B-D-F §5, 3b; veja Rob. 530f); a variante textual <span class=\"greek\">ἔβαλον</span> decorre de não se ter reconhecido esse uso raro. <span class=\"greek\">καλῶς</span> <span class=\"greek\">ἔλαβόν</span> <span class=\"greek\">σε</span>; (as jovens) trataram-te bem? Hs 9, 11, 8.</p><p class=\"entry-text\">⑥ fazer uma escolha, escolher, selecionar <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">λαμβανόμενος</span> que é escolhido dentre os seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a> (cf. Num 8:6; Am 2:11; Just., D. 130, 3). A ênfase não recai sobre o sexo, mas sobre a condição humana do sumo sacerdote, em contraste com a do Messias único vveja 5.</p><p class=\"entry-text\">⑦ aceitar como verdadeiro, acolher <span class=\"greek\">τὶ</span> algo figuradamente <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματά</span> <span class=\"greek\">τινος</span> acolher as palavras de alguém (e tomá-las como orientação) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:48</a>; 17:8; AcPl Ha 1, 6 (veja <span class=\"greek\">καρδία</span> 1b<span class=\"greek\">β</span>). <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> acolher o ensinamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:16</a> (para <span class=\"greek\">μετὰ</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">λ</span>., cf. PIand 13, 18 <span class=\"greek\">ἵνα</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἀπολάβωμεν</span>).</p><p class=\"entry-text\">⑧ entrar em uma relação íntima, receber, apropriar-se de, apreender ou compreender mental ou espiritualmente (Soph., Pla. e outros) da apreensão mística de Cristo (opp. <span class=\"greek\">κατελήμφθην</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">Χριστοῦ</span>) <span class=\"greek\">ἔλαβον</span> (i.e. <span class=\"greek\">Χριστόν</span>) fiz dele o meu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a>.</p><p class=\"entry-text\">⑨ Usos especiais: o Antigo Testamento é a origem de <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">πρόσωπον</span> manifestar parcialidade ou favoritismo (veja <span class=\"greek\">πρόσωπον</span> 1b<span class=\"greek\">α</span> end) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a>; B 19:4; D 4:3.—<span class=\"greek\">θάρσος</span> <span class=\"greek\">λ</span>. criar coragem veja <span class=\"greek\">θάρσος</span>; <span class=\"greek\">πεῖράν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">λ</span>. experimentar algo (Pla., Prot. 342a; 348a, Gorg. 448a; X., Cyr. 6, 1, 28; Polyb. 1, 75, 7; 2, 32, 5; 5, 100, 10; Aelian, VH 12, 22; Dt 28:56; Jos., Ant. 8, 166; diff. Dio Chrys. 50, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a> (essa expressão tem significado diferente no v. 36; veja 10b adiante).—<span class=\"greek\">συμβούλιον</span> <span class=\"greek\">λαμβάνειν</span> consultar (alguém), literalmente «tomar conselho», é um latinismo (consilium capere; veja B-D-F §5, 3b; Rob. 109) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:7</a>; 28:12; com <span class=\"greek\">ὅπως</span> seguido 22:15; seguido por <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> contra alguém e <span class=\"greek\">ὅπως</span> 12:14; seguido por <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> e <span class=\"greek\">ὥστε</span> 27:1. <span class=\"greek\">οὐ</span> <span class=\"greek\">λήψῃ</span> <span class=\"greek\">βουλὴν</span> <span class=\"greek\">πονηρὰν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">σου</span> D 2:6.</p><p class=\"entry-text\">⑩ ser o destinatário, receber, conseguir, obter</p><p class=\"entry-text\">ⓐ em uso absoluto, <span class=\"greek\">λαβών</span> (de um porco faminto) quando recebeu alguma coisa B 10:3. (Em oposição a <span class=\"greek\">αἰτεῖν</span>, as Appian, Fgm. [I p. 532–36 Viereck-R.] 23 <span class=\"greek\">αἰτεῖτε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λαμβάνετε</span>; PGM 4, 2172) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:24</a>. (Em oposição a <span class=\"greek\">διδόναι</span> as Thu. 2, 97, 4 <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">διδόναι</span>; Ael. Aristid. 34 p. 645 D.; Herm. Wr. 5, 10b; Philo, Deus Imm. 57; SibOr 3, 511) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a>; B 14:1; but em D 1:5, porém, <span class=\"greek\">λ</span>. tem antes o sentido «ativo» de aceitar uma doação (as <span class=\"greek\">ἵνα</span> <span class=\"greek\">λάβῃ</span> <span class=\"greek\">ἐξουσίαν</span> TestJob 8:2).</p><p class=\"entry-text\">ⓑ com acusativo de coisa <span class=\"greek\">τὶ</span> algo (Da 2:6; OdeSol 11:4 <span class=\"greek\">σύνεσιν</span>; TestJob 24:9 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἄρτους</span> al.; ApcEsdr 5:13 p. 30, 11 Tdf. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">ψωμίον</span> receber o pedaço de pão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:30</a>. <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">δωρεάν</span> água da vida gratuitamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:17</a>. <span class=\"greek\">μισθόν</span> (veja o verbete, 1 e 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:41ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:8</a>, 14; AcPlCor 2:36 (TestSol 1:2, 10). Dinheiro: <span class=\"greek\">ἀργύρια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a>; <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">δηνάριον</span> um denário para cada um <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:9f</a>. <span class=\"greek\">ἐλεημοσύνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:3</a>. <span class=\"greek\">βραχύ</span> <span class=\"greek\">τι</span> um pouco ou um bocado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:7</a>; vida eterna <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:30</a> (Jos., C. Ap. 2, 218 <span class=\"greek\">βίον</span> <span class=\"greek\">ἀμείνω</span> <span class=\"greek\">λαβεῖν</span>); o Espírito (schol. on Plato 856e <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:4</a>; perdão do pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:43</a> (Just., D. 54, 1); graça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>; cf. 5:17; o prêmio do vencedor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24f</a>; a coroa da vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:12</a> (cf. Wsd 5:16 <span class=\"greek\">λ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">διάδημα</span>). <span class=\"greek\">συμφύγιον</span>/<span class=\"greek\">σύμφυτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅπλον</span> <span class=\"greek\">εὐδοκίας</span> <span class=\"greek\">λάβωμεν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">χριστόν</span> o sentido desta oração, restaurada com base em AcPl Ha 8, 23–24 e AcPl Ox 1602, 33–35 (=BMM recto 29–31) resulta como segue: e tomemos Jesus Cristo como nosso refúgio/aliado e escudo, garantia da boa vontade de Deus para conosco. A chuva temporã e serôdia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a>. <span class=\"greek\">ἔλεος</span> receber misericórdia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a> (Just., D. 133, 1). <span class=\"greek\">λ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> (<span class=\"greek\">θεοῦ</span>) receber o nome do Filho de Deus (no batismo) Hs 9, 12, 4. <span class=\"greek\">διάδοχον</span> receber um sucessor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:27</a> (cf. Plínio, o Jovem, Ep. 9, 13 successorem accipio). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπισκοπὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λαβέτω</span> <span class=\"greek\">ἕτερος</span> que outro receba seu cargo 1:20 (Ps 108:8). <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀπολογίας</span> <span class=\"greek\">λ</span>. (<span class=\"greek\">τόπος</span> 4) 25:16. <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">εὐχαριστίας</span> receber algo com gratidão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:4</a> (mas veja 1 acima, ao final.—Sobre a construção com <span class=\"greek\">μετά</span>, cf. Libanius, Or. 63 p. 392, 3 F. <span class=\"greek\">μετὰ</span> <span class=\"greek\">ψόγου</span> <span class=\"greek\">λ</span>.). <span class=\"greek\">τί</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔλαβες</span>; que tens que não tenhas recebido? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:7</a> (Alciphron 2, 6, 1 <span class=\"greek\">τί</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐμῶν</span> <span class=\"greek\">λαβοῦσα</span> <span class=\"greek\">ἔχεις</span>;). De punições (cf. <span class=\"greek\">δίκην</span> <span class=\"greek\">λ</span>. Hdt. 1, 115; Eur., Bacch. 1312. <span class=\"greek\">ποινάς</span> Eur., Tro. 360. <span class=\"greek\">πληγάς</span> Philyllius Com. [V a.C.] 11 K.; GrBar 4:15 <span class=\"greek\">καταδίκην</span>; Jos., Ant. 14, 336 <span class=\"greek\">τιμωρίαν</span>) <span class=\"greek\">λ</span>. <span class=\"greek\">περισσότερον</span> <span class=\"greek\">κρίμα</span> receber punição ainda mais severa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a> [14] variante textual (cf. <span class=\"greek\">κρίμα</span> 4b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:1</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀνθεστηκότες</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">λήμψονται</span> os que resistem trarão condenação sobre si mesmos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:2</a>. <span class=\"greek\">πεῖράν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">λ</span>. conhecer, experimentar, sofrer algo (X., An. 5, 8, 15; Polyb. 6, 3, 1; 28, 9, 7; 29, 3, 10; Diod S 12, 24, 4 <span class=\"greek\">τὴν</span> <span class=\"greek\">θυγατέρα</span> <span class=\"greek\">ἀπέκτεινεν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὕβρεως</span> <span class=\"greek\">λάβῃ</span> <span class=\"greek\">πεῖραν</span>; 15, 88, 4; Jos., Ant. 2, 60; Preisigke, Griech. Urkunden des ägypt. Museums zu Kairo [1911] 2, 11; 3, 11 <span class=\"greek\">πεῖραν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">δαίμονος</span>) <span class=\"greek\">μαστίγων</span> <span class=\"greek\">πεῖραν</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:36</a> (a expressão tem sentido diferente no v. 29; veja 9b above).</p><p class=\"entry-text\">ⓒ Empregado também como perífrase de voz passiva: <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">λ</span>. ser edificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:5</a>. <span class=\"greek\">περιτομήν</span> ser circuncidado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:23</a> (Just., D. 23, 5 al.). <span class=\"greek\">τὸ</span> <span class=\"greek\">χάραγμα</span> receber uma marca, isto é, ser marcado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:9</a>, 11; 19:20; 20:4. <span class=\"greek\">καταλλαγήν</span> ser reconciliado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:11</a>. <span class=\"greek\">ὑπόμνησίν</span> <span class=\"greek\">τινος</span> ser lembrado de, isto é, recordar algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a> (Just., D 19, 6 <span class=\"greek\">μνήμην</span> <span class=\"greek\">λαμβάνητε</span>); <span class=\"greek\">λήθην</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">λ</span>. esquecer algo (Timocles Com. [IV a.C.], Fgm. 6, 5 K.; Aelian, VH 3, 18 end, HA 4, 35; Jos., Ant. 2, 163; 202; 4, 304; Just., D. 46, 5 <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λήθη</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">λαμβάνῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>; <span class=\"greek\">χαρὰν</span> <span class=\"greek\">λ</span>. experimentar alegria, alegrar-se Hv 3, 13, 2 ; GJs 12:2; <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">λ</span>. ser iniciado, ter início (Pla e outros; Polyb. 1, 12, 9; Sext. Emp., Phys. 1, 366; Aelian, VH 2, 28; 12, 53; Dio Chrys. 40, 7; Philo, Mos. 1, 81 <span class=\"greek\">τρίτον</span> [<span class=\"greek\">σημεῖον</span>] … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">λαβὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Αἰγύπτῳ</span>; Just., D. 46, 4 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">λαβούσης</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">περιτομῆς</span>; Ath. 19, 2 <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">λαβόντος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a>; ApcPt Rainer ln. 19.—<span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> receber algo de alguém (Epict. 4, 11, 3 <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; Herm. Wr. 1, 30; ApcMos 19 <span class=\"greek\">ὅτε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄρκον</span>; Just., D. 78, 10 <span class=\"greek\">τῶν</span> <span class=\"greek\">λαβόντων</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:27</a>; 3:22. Também <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> (Pisander Epicus [VI a.C.] Fgm. 5 [em Athen. 11, 469d]; Diod S 5, 3, 4 <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; TestAbr A 5 p. 82, 8 [Stone p. 12] <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐχὴν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῶν</span>; Just., A I, 60, 3 <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λεγομένην</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Μωυσέα</span>.—<span class=\"greek\">παρά</span> A3a<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:18b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:33</a>; 3:5; 20:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:7</a>; 2J 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:28</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰάσονος</span> receber caução de Jasom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:9</a> (veja <span class=\"greek\">ἱκανός</span> 1). <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> receber algo dado por alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:24</a>. <span class=\"greek\">κλῆρον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μερισμὸν</span> <span class=\"greek\">λαμβάνοντες</span> AcPl Ha 8, 18//Ox 1602, 22f [<span class=\"greek\">λαβόντες</span>]=BMM recto 23f (veja <span class=\"greek\">κλῆρος</span> 2). <span class=\"greek\">λ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> receber algo de certa quantidade de alguma coisa: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πληρώματος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐλάβομεν</span> <span class=\"greek\">χάριν</span> de sua plenitude recebemos favor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:16</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐλάβετε</span> Hs 9, 24, 4.—<span class=\"greek\">λ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">νεκροὺς</span> <span class=\"greek\">αὐτῶν</span> (veja <span class=\"greek\">ἀνάστασις</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:35</a>. Sobre <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρὶ</span> <span class=\"greek\">εἴληφα</span> (LXX), GJs 4:2 e 4, veja <span class=\"greek\">γαστήρ</span> 2 e <span class=\"greek\">συλλαμβάνω</span> 3.—B. 743. Schmidt, Syn. III 203–33. DELG. M-M. EDNT. TCom Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λάμεχ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λάμεχ</span>, <span class=\"greek\">ὁ</span> indeclinável (<span class=\"hebrew\" dir=\"rtl\">לֶמֶךְ</span>, em pausa <span class=\"hebrew\" dir=\"rtl\">לָמֶךְ</span>) Lameque (Gen 4:18ff; 5:25ff; Philo; TestBenj 7:4.—En 10:1 Raderm. apresenta <span class=\"greek\">Λέμεχ</span>, mas 106:1, 4 al. Bonner <span class=\"greek\">Λάμεχ</span>; Joseph. <span class=\"greek\">Λάμεχος</span>, <span class=\"greek\">ου</span> [Ant. 1, 79]), pai de Noé; na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:36</a> (cf. 1 Ch 1:3).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμπάς, άδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμπάς</span>, <span class=\"greek\">άδος</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λάμπω</span>; Aeschyl., Hdt.+; ins, pap, LXX, TestSol 10:8; TestJob; ParJer 3:2; Philo, Joseph., SibOr; Mel., Fgm. 8b [<span class=\"greek\">περὶ</span> <span class=\"greek\">λουτροῦ</span>] 3; empréstimo no vocabulário rabínico).</p><p class=\"entry-text\">① tocha (nesse sentido, na tragédia; Thu. 3, 24, 1; Polyb. 3, 93, 4; Herodian 4, 2, 10; OGI 764, 43; 50; 54; Sir 48:1; Jos., Bell. 6, 16, Ant. 5, 223; SibOr Fgm. 3, 44), portanto, provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:3</a> com <span class=\"greek\">φανοί</span> (=lanternas; os dois termos reunidos Dionys. Hal. 11, 40, 2; PLond II, 1159, 59 p. 113 [II d.C.]=Mitt-Wilck. I/2, p. 493).—Fenômenos celestes semelhantes a tochas acesas (Diod S 16, 66; Ps.-Aristot., De Mundo 4; Erot. Gr. Fgm. pap ed. BLavagnini 1922, Herp. 47; PGM 4, 2939ff <span class=\"greek\">ἀστέρα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">λαμπάδα</span>) <span class=\"greek\">ἀστὴρ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">καιόμενος</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">λαμπάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:10</a> (Diod S 15, 50, 2 <span class=\"greek\">ὤφθη</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολλὰς</span> <span class=\"greek\">νύκτας</span> <span class=\"greek\">λαμπὰς</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">καομένη</span>; Artem. 2, 9 p. 92, 22 <span class=\"greek\">λαμπάδες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">καιόμεναι</span>). Cf. <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">λαμπάδες</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">καιόμεναι</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θρόνου</span> 4:5 (<span class=\"greek\">λαμπάδες</span> <span class=\"greek\">πυρός</span>, como em Eutecnius 4 p. 39, 6; Gen 15:17; Na 2:5; Da 10:6; Philo, Rer. Div. Her. 311.—<span class=\"greek\">λαμπάδες</span> <span class=\"greek\">καιόμεναι</span>, como em Artem. [veja acima]; Job 41:11).</p><p class=\"entry-text\">② lâmpada (assim em POxy 1449 [III d.C.]; Jdth 10:22; Da 5:5 Theod.) com pavio e reservatório de óleo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a>, 3f, 7f (segundo FZorell, Verbum Domini 10, 1930, 176–82; HAlmqvist, Plut. u. d. NT ’46, 46 [Mor. 263f] a tocha nupcial [veja 1] é aqui referida); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:8</a>. É incerto se <span class=\"greek\">λαβέτωσαν</span> <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">λαμπάδα</span> que cada (filha) tome uma lâmpada (ou tocha) GJs 7:2 (‘lampe’ deStrycker; ‘flambeau’ EAmann, Le Protévangile de Jacques et ses remaniements latins 1910) pertence à acepção 1 ou 2 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:35</a>).—RAC VII 154–217. B. 484. DELG s.v. <span class=\"greek\">λάμπω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμπηδών, όνος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμπηδών</span>, <span class=\"greek\">όνος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">λάμπη</span> + sufixo-<span class=\"greek\">δών</span> [Schwyzer I 529]; Hippocr. V 632 L.; Epicurus 45, 8 Us.; Diod S 3, 37, 9; Plut.; Aelian, NA 2, 8 p. 36, 16; Artem. 5, 90; Herm. Wr. 10, 4b; PGM 4, 531; Is 58:11 Aq.; Jos., Ant. 3, 207) claridade, brilho Hs 9, 2, 2.—DELG s.v. <span class=\"greek\">λάμπω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμπρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμπρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">λάμπω</span>; Hom.+; ins, pap, LXX, TestSol, TestAbr, Test12Patr, JosAs; ApcMos 33; Philo, Joseph., Just., Mel.)</p><p class=\"entry-text\">① referente ao que irradia luz, brilhante de corpos celestes (Hom. e outros; X., Mem. 4, 7, 7; EpJer 59; TestNapht 5:4; Cat. Cod. Astr. IX/1, 174, 30) o sol (Philo, Somn. 2, 282) Hs 9, 17, 4. A estrela da manhã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:16</a>.</p><p class=\"entry-text\">② referente ao que está livre de impedimentos à percepção nítida, claro, transparente (Aeschyl., Eum. 695; X., Hell. 5, 3, 19) <span class=\"greek\">ποταμὸν</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">λαμπρὸν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κρύσταλλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:1</a>.</p><p class=\"entry-text\">③ referente à qualidade daquilo que resplandece</p><p class=\"entry-text\">ⓐ de vestimentas, especialmente as brancas: brilhante, resplandecente (Od. 19, 234; Polyb. 10, 4, 8; 10, 5, 1; SIG 1157, 39f <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐσθῆσιν</span> <span class=\"greek\">λαμπραῖς</span>; Philo, De Jos. 105 <span class=\"greek\">λ</span>. <span class=\"greek\">ἐσθής</span>) <span class=\"greek\">ἱματισμὸς</span> <span class=\"greek\">λαμπρότατος</span> uma veste de brilho intenso Hv 1, 2, 2. <span class=\"greek\">ἐσθής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:11</a> (PJoüon, RSR 26, ’36, 80–85); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:2f</a>. <span class=\"greek\">στόλη</span> (Jos., Vi. 334; TestSol 10:28 C <span class=\"greek\">στολὰς</span> <span class=\"greek\">λαμπράς</span>; TestAbr A 16 p. 97, 8f [Stone p. 42] <span class=\"greek\">στολὴν</span> <span class=\"greek\">λαμπροτάτην</span>; JosAs 14:15) GPt 13:55. <span class=\"greek\">βύσσινον</span> <span class=\"greek\">λ</span>. <span class=\"greek\">καθαρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:8</a> (cf. Jos., Ant. 8, 72). <span class=\"greek\">λίνον</span> <span class=\"greek\">καθαρὸν</span> <span class=\"greek\">λ</span>. 15:6.</p><p class=\"entry-text\">ⓑ de outros objetos: reluzente, brilhante, pedras Hv 3, 2, 4b; Hs 9, 3, 3; 9, 4, 6; 9, 6, 7f; 9, 8, 7; 9, 9, 3f; 9, 17, 3; 9, 30, 2 e 4; cf. <span class=\"greek\">οἰκοδομὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> 9, 30, 1. <span class=\"greek\">ἐπάρασα</span> <span class=\"greek\">ῥάβδον</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">λαμπράν</span> quando ela ergueu uma espécie de vara cintilante Hv 3, 2, 4a.</p><p class=\"entry-text\">④ como substantivo, <span class=\"greek\">τὰ</span> <span class=\"greek\">λαμπρά</span>, esplendor (Philo, In Flacc. 165, Leg. ad Gai. 327; Mel., HE 26, 8), no qual um homem rico se deleita (cf. Jos., Ant. 12, 220 <span class=\"greek\">δωρεὰς</span> <span class=\"greek\">δοὺς</span> <span class=\"greek\">λαμπράς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:14</a>.—DELG s.v. <span class=\"greek\">λάμπω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμπρότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμπρότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λαμπρός</span>; Hdt.+; ins, pap, LXX, EpArist, Philo, Joseph.) em geral, «brilho, esplendor».</p><p class=\"entry-text\">① o estado de ser esplêndido, resplandecente (X., An. 1, 2, 18 do esplendor das armas; Jos., Bell. 5, 271, Ant. 12, 81) brilho do sol (Vi. Aesopi W 115. De uma constelação Diod S 15, 50, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:13</a>.</p><p class=\"entry-text\">② qualidade pessoal excepcional, distinção, brilhantismo sentido figurado derivado de 1: usado especialmente para quem sobressai pela inteligência e pelo espírito empreendedor (Polyb. 32, 8, 1 do brilhantismo pessoal em contraste com a perda do vigor físico; Diod S 2, 22, 3; 4, 10, 2; 4, 40, 1 <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">λαμπρότητι</span>; EpArist 16; Jos., Ant. 11, 342 de um grupo de recepção que oferece tratamento de pessoa muito importante) <span class=\"greek\">λ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span> brilhantismo na retidão, isto é, além do comum, 1 Cl 35:2.—DELG s.v. <span class=\"greek\">λάμπω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λαμπρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λαμπρῶς</span> advérbio derivado de <span class=\"greek\">λαμπρός</span> (Aeschyl.+; SIG 545, 12; 1045, 15; PSI 406, 30; Jos., Ant. 6, 15 al.) esplendidamente <span class=\"greek\">εὐφραίνεσθαι</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">λαμπρῶς</span> banquetear-se suntuosamente todos os dias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:19</a> (PYadin 15, 10; 26 de um estilo de vida opulento; PGM 1, 111 <span class=\"greek\">ἐξαρτίσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεῖπνον</span> <span class=\"greek\">λαμπρῶς</span>; veja <span class=\"greek\">δαπανάω</span> 1).—M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λάμπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λάμπω</span> futuro <span class=\"greek\">λάμψω</span>; 1 aoristo <span class=\"greek\">ἔλαμψα</span> (Hom.+; LXX, En, TestSol; TestAbr B 7 p. 111, 10f [Stone p. 70]; Test12Patr; SyrBar 12:2 [?]; GrBar, Joseph., SibOr; inscrição cristã em OGI 610, 1f [VI d.C.] <span class=\"greek\">φῶς</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">ἔλαμψεν</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">σκότος</span> <span class=\"greek\">ἐκάλυπτεν</span>; Just.) emitir raios de luz, brilhar (Jos., Ant. 3, 218 de pedras preciosas) de uma lâmpada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; de um relâmpago <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:24</a>.—resplandecer, irradiar luz, cintilar (Chariton 1, 9, 5 de uma espada reluzente; Jos., Ant. 5, 284) luz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:7</a>; uma estrela (cf. IAndrosIsis [I a.C.] 23; Bar 3:34; SibOr 3, 334 <span class=\"greek\">ἀστὴρ</span> <span class=\"greek\">λάμψει</span>) IEph 19:2; sol (Archilochus [VII a.C.] 74, 4 Diehl2; SyrBar 12:2 <span class=\"greek\">ἀκτίνες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">λάμπουσιν</span>; GrBar 7:5 <span class=\"greek\">λάμψαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span>; 9:8) GPt 6:22. Do rosto de Jesus transfigurado <span class=\"greek\">ὡς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> (cf. EpJer 66; En 14:18; 106:2; TestLevi 18:4; diferentemente, mas acerca de uma pessoa SEG XXVIII, 1251, 2 [III ou IV d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:2</a>. Da luz que brilhou na criação por ordem de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6a</a>. De um anjo <span class=\"greek\">ὁ</span> <span class=\"greek\">λάμπων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φαίνων</span> AcPl Ha 3, 36.—Em sentido figurado, com <span class=\"greek\">φῶς</span> (cf. Pr 4:18; Tob 13:13 S; Is 9:1) brilhar: <span class=\"greek\">λαμψάτω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φῶς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a> (cf. SEG above). Quanto a Deus, provavelmente «resplandecer» <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ὅς</span> <span class=\"greek\">ἔλαμψεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">ἡμῶν</span> Deus, que resplandeceu em nossos corações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6b</a> (talvez «refletir», como em PGM 13, 770 dos olhos celestes de uma divindade <span class=\"greek\">λάμποντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">κόραις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>. GMacRae, Anti-Dualist Polemic in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6</a>? TU 102, ’68, 420–31).—DELG. New Docs 3, 49f. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0215-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λανθάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λανθάνω</span> (Hom.+) futuro <span class=\"greek\">λήσω</span> (Just., A I, 35, 1; Ath. 22:2) ou <span class=\"greek\">λήσομαι</span> (2 Km 18:13; Ath., R. 10 p. 59, 2); 2 aoristo <span class=\"greek\">ἔλαθον</span>; perfeito 3ª pessoa do singular <span class=\"greek\">λέληθεν</span> conseguir escapar à atenção ou à percepção, passar despercebido, ficar oculto em uso absoluto (Jos., Bell. 3, 343; Just., A I, 11, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:47</a>; MPol 6:2.—<span class=\"greek\">λανθάνει</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινα</span> algo está oculto a alguém, escapa à sua percepção (Hom. e outros; BGU 531 II, 13; POxy 34 verso III, 3; 1253, 22; Job 34:21 <span class=\"greek\">λέληθεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">οὐδέν</span>; EpArist 132; Jos., Ant. 17, 38, Vi. 83; JosAs 6:3 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">κρυπτὸν</span> <span class=\"greek\">λέληθεν</span> <span class=\"greek\">αὐτῷ</span> [-<span class=\"greek\">όν</span> variante textual]; Just., A I, 12, 3) IEph 19:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:8</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">λέληθεν</span> <span class=\"greek\">αὐτόν</span> 1 Cl 21:3; cf. 27:6; IEph 14:1; 15:3; Pol 4:3. <span class=\"greek\">λανθάνειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πείθομαι</span> <span class=\"greek\">οὐθέν</span> não consigo acreditar que alguma dessas coisas tenha escapado à percepção dele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:26</a>. [<span class=\"greek\">ὅσα</span>] <span class=\"greek\">ὑ̣μ̣ᾶ̣ς</span> <span class=\"greek\">λανθάνει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπομνημονεύω</span>, <span class=\"greek\">ἀ̣π̣α̣</span>[<span class=\"greek\">γγέλω</span> <span class=\"greek\">ὑμῖν</span>]tudo quanto vos escapou à percepção e de que eu (Maria) me lembro, eu [vos declaro.] Ox 3525, 18.—Aquilo que passa despercebido também pode ser expresso por uma oração introduzida por <span class=\"greek\">ὅτι</span> (X., Mem. 3, 5, 24; Isocr., Ep. 6, 12; Dio Chrys. 16 [33], 37) <span class=\"greek\">λανθάνει</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">θέλοντας</span> <span class=\"greek\">ὅτι</span> ao sustentar isso, escapa-lhes à percepção (isto é, esquecem ou ignoram) que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:5</a> (veja <span class=\"greek\">θέλω</span> 4). Igualmente, por meio do particípio (Maximus Tyr. 4, 6b; Jos., Vi. 425; Just., A I, 12, 3; Ath. 22, 2; B-D-F §414, 3; Rob. 1120) <span class=\"greek\">ἔλαθόν</span> <span class=\"greek\">τινες</span> (entenda-se <span class=\"greek\">ἑαυτούς</span>) <span class=\"greek\">ξενίσαντες</span> <span class=\"greek\">ἀγγέλους</span> alguns, sem o saber, hospedaram anjos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:2</a> (cf. Hdt. 1, 44 <span class=\"greek\">φονέα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">ἐλάνθανε</span> <span class=\"greek\">βόσκων</span>=sem o saber, alimentou o assassino de seu filho; X., Mem. 4, 3, 9 al.; Lucian, De Merc. Cond. 7 <span class=\"greek\">ἔλαθον</span> <span class=\"greek\">γηράσαντες</span>=tinham envelhecido sem perceber).—DELG. M-M. Spicq.</p></section></article>"};
